function updateJobFilter(){
  document.querySelectorAll('[data-job-filter]').forEach(button=>{const active=button.dataset.jobFilter===jobFilter;button.classList.toggle('active',active);button.setAttribute('aria-pressed',String(active));});
}
function choosePasteKind(){
  if(state.runner.active||updateRequired())throw Error('진행 중인 작업이 끝난 뒤 입력하세요.');
  modal('어떤 표를 붙여넣을까요?',`<div class="paste-choices"><button class="paste-choice" id="pasteMessages"><strong>예약표 가져오기</strong><span>받는 사람 · 날짜 · 시간 · 내용이 준비된 표</span></button><button class="paste-choice" id="pasteWorkflow"><strong>자료로 메시지 만들기</strong><span>일정·배정표의 각 행에 안내 문구 적용하기</span></button></div>`,[{text:'닫기',action:closeModal}]);
  $('pasteMessages').addEventListener('click',()=>{closeModal();openBatchEditor();$('batchPastePanel').open=true;$('batchPaste').focus();});
  $('pasteWorkflow').addEventListener('click',()=>openWorkflowPaste().catch(failure));
}
async function openWorkflowPaste(){
  closeModal();await openWorkflow();wf.source.kind='paste';wf.snapshot=null;wf.snapshotId='';wf.preview=null;wf.dirty=true;wf.step=1;showView('workflow');$('wfPaste')?.focus();
}
function previewJobs(jobs){return jobs.map(job=>`<article class="preview-item"><header><span>${esc(recipientLabel(job))}</span><span>${esc(job.scheduled)} · 한국시간</span></header><p class="actual-recipients">실제 수신자 표시:\n${esc(expectedRecipients(job))}</p><h3>${esc(displayTitle(job.title))}</h3><pre>${esc(job.body)}</pre>${(job.attachments||[]).length?`<footer>첨부: ${job.attachments.map(esc).join(' / ')}</footer>`:''}</article>`).join('');}
function details(id){
  const job=state.jobs.find(job=>job.id===id);if(!job)return;
  const busy=!!state.runner.active,editable=!locked.has(job.status)&&job.status!=='preparing',buttons=[{text:'닫기',action:closeModal}];
  if(editable)buttons.push({text:'수정',disabled:busy,action:()=>{closeModal();editJob(job);}},{text:'목록에서 삭제',quiet:true,disabled:busy,action:()=>removeJobs([id])},{text:'예약 전 검토',primary:true,disabled:busy,action:()=>run('register',[id])});
  if(['needs_review','uncertain'].includes(job.status))buttons.push({text:job.status==='uncertain'?'등록 여부 확인 기록':'확인 기록 남기기 · 선택',primary:job.status==='uncertain',quiet:job.status==='needs_review',disabled:busy,action:()=>{modal('등록 확인 기록',`<p>쿨메신저에서 이 예약의 수신자·예약시각·내용을 직접 확인했다면 기록을 남길 수 있습니다. 확인 기록은 선택이며, 다음 메시지 등록에 필요하지 않습니다.</p><label>확인 메모<input id="reviewNote" type="text" placeholder="개인정보 없이 확인 결과를 입력하세요"></label>`,[{text:'취소',action:closeModal},{text:'확인 기록 저장',primary:true,action:async()=>{await api('review',{id,note:$('reviewNote').value});closeModal();await refresh();}}]);}});
  const note=job.status==='confirmed'?'<p class="hint">등록된 메시지는 수정·재등록할 수 없습니다. 지난 메시지는 목록에서 정리할 수 있습니다.</p>':job.status==='prepared'?'<p class="notice">입력한 내용을 확인한 뒤 같은 작성창에서 예약 등록을 이어서 실행할 수 있습니다. 아직 보내기는 누르지 않았습니다.</p>':job.status==='needs_review'?'<p class="notice request-done">등록 요청을 마쳤습니다. 확인 기록 남기기는 선택입니다. 실제 접수 결과는 사용자가 확인할 수 있습니다. 중복 등록을 막기 위해 다시 보내지 않습니다.</p>':job.status==='uncertain'?'<p class="notice warning">보내기 도중 결과가 불명확해 멈췄습니다. 이 메시지는 자동 재등록하지 않습니다. 쿨메신저에서 등록 여부를 직접 확인하세요.</p>':'';
  const diagnostics=editable?`<details class="troubleshooting" ${state.connection_mode!=='automatic'&&!profile.tested?'open':''}><summary>문제 해결</summary><p class="hint">수동 화면 연결이나 입력 문제를 확인할 때 사용하세요.</p><div class="button-group">${[['simulate','모의 실행'],['inspect','작성창만 대조'],['prepare','1건 자동 입력']].map(([mode,label])=>`<button type="button" class="button small" data-detail-mode="${mode}" ${busy||state.offline&&mode!=='simulate'?'disabled':''}>${label}</button>`).join('')}</div></details>`:'';
  modal('메시지 내용',note+previewJobs([job])+`<p>${badge(job)} ${esc(job.note)}</p>`+(job.errors?.length?`<div class="error-box">${job.errors.map(error=>`<p>${esc(error)}</p>`).join('')}</div>`:'')+diagnostics,buttons);
  $('modalBody').querySelectorAll('[data-detail-mode]').forEach(button=>button.addEventListener('click',()=>run(button.dataset.detailMode,[id]).catch(failure)));
}
async function removeJobs(ids){modal('목록에서 삭제',`<p>${ids.length}건의 초안을 삭제할까요? 등록 시도 기록은 삭제하지 않습니다. 목록 삭제는 쿨메신저 예약 취소가 아닙니다.</p>`,[{text:'취소',action:closeModal},{text:'삭제',action:async()=>{await api('remove',{ids});ids.forEach(id=>selected.delete(id));closeModal();await refresh();}}]);}
async function importPreview(result,title='가져온 메시지 확인'){const errors=result.errors||[],jobs=result.jobs||[];modal(title,`<p>${jobs.length}건을 초안으로 추가합니다. 예약은 등록하지 않습니다.</p>${errors.length?`<div class="error-box">${errors.map(esc).join('<br>')}</div>`:''}${previewJobs(jobs)}`,[{text:'취소',action:closeModal},{text:`${jobs.length}건 초안 저장`,primary:true,disabled:!jobs.length,action:async(button)=>{button.disabled=true;try{const before=new Set(state.jobs.map(job=>job.id));const result=await api('import/commit',{jobs});jobFilter='all';updateJobFilter();closeModal();$('editor').close();await refresh();selected=new Set(state.jobs.filter(job=>!before.has(job.id)).map(job=>job.id));selectionMode=selected.size>0;refreshTable();showView('jobs');toast(`${result.saved}건 저장${result.errors.length?' · 중복·오류 '+result.errors.length+'건 제외':''}`);if(result.errors.length)modal('일부 초안을 저장하지 못했습니다.',`<div class="error-box">${result.errors.map(esc).join('<br>')}</div>`,[{text:'확인',action:closeModal}]);}catch(error){button.disabled=false;throw error;}}}]);}
async function fileBase64(file){if(file.size>10*1024*1024)throw Error('10MB 이하의 엑셀·CSV 파일을 사용하세요.');const buffer=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<buffer.length;i+=0x8000)binary+=String.fromCharCode(...buffer.subarray(i,i+0x8000));return btoa(binary);}
async function importSelected(file){if(file){batchChoices={};showBatchPreview(await api('batch/import',{name:file.name,data:await fileBase64(file)}));}}
async function download(path,name){const response=await fetch('/api/'+path,{headers:{'X-Cool-Token':token}});if(!response.ok)throw Error('파일을 내보내지 못했습니다.');const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function run(mode,ids=[...selected]){
  if(!ids.length)throw Error('메시지를 선택하세요.');
  const planMode=mode==='register'&&state.offline?'simulate':mode,plan=await api('plan',{ids,mode:planMode,...(mode==='register'?{result_confirmation_mode:resultConfirmationMode()}: {})});
  const trialButton=canOfferInputTrial(mode,ids,plan)?[{text:'1건 자동 입력으로 확인',primary:true,action:()=>run('prepare',ids)}]:[],modeTitle={simulate:'모의 실행',inspect:'작성창만 대조',prepare:'1건 자동 입력 · 보내지 않음',register:'예약 내용 확인'}[mode];
  let html=mode==='register'?reviewSummary(plan.jobs,plan.errors)+registrationGuide(plan.jobs,plan,'plan-registration-guide')+`<p class="hint">수신자·시각·내용을 검토한 뒤 한 번에 등록하세요.${state.offline?' 모의 실행 모드에서는 실제 등록이 비활성화됩니다.':''}</p>`:`<p>${mode==='simulate'?'입력값과 첨부파일을 검사합니다. 쿨메신저는 조작하지 않습니다.':mode==='inspect'?'쿨메신저에 직접 입력한 내용을 읽어 비교합니다. 키보드·마우스 조작과 전송은 없습니다.':'프로그램이 쿨메신저에 내용을 입력하고 대조합니다. 완료까지 PC 사용을 멈춰 주세요. 보내기는 누르지 않습니다. 확인 후 같은 작성창에서 등록을 이어갈 수 있습니다.'}</p>`;
  if(plan.errors.length)html+=`<div class="error-box" role="alert">${plan.errors.map(item=>`<strong>${esc(displayTitle(item.title))}</strong>${item.errors.map(error=>`<p>${esc(error)}</p>`).join('')}`).join('')}</div>`;
  html+=mode==='register'?reviewControls('plan')+registrationPreview(plan.jobs,plan.errors):previewJobs(plan.jobs);
  modal(modeTitle,html,[{text:'닫기',action:closeModal},...trialButton,{text:mode==='register'?`${plan.jobs.length}건 한 번에 등록`:'실행',describedBy:mode==='register'?'plan-registration-guide':undefined,primary:true,disabled:!!plan.errors.length||(mode==='register'&&state.offline),action:async(button)=>{if(mode==='register'&&state.offline)throw Error('모의 실행 모드에서는 실제 예약을 등록하지 않습니다.');button.disabled=true;try{await api('run',{plan_id:plan.id,phrase:mode==='register'?'예약 등록':''});closeModal();await refresh();focusRunPanel();}catch(error){button.disabled=false;throw error;}}}]);
  if(mode==='register')bindReviewControls('plan');
}
async function loadHistory(){const rows=await api('events');$('historyRows').innerHTML=rows.length?rows.map(row=>`<div class="history-item"><time>${esc(row.at.replace('T',' '))}</time><span class="badge ${esc(row.kind)}">${esc(state.states[row.kind]||row.kind)}</span><p>${esc(row.message)}</p></div>`).join(''):'<div class="empty">아직 실행 기록이 없습니다.</div>';}
function help(){modal('사용 안내',`<p>새 메시지, 여러 메시지 입력, 예약표 가져오기, 표 붙여넣기로 예약할 내용을 준비하세요. 한 메시지에 여러 수신자를 넣을 수 있습니다.</p><p>미리보기에서 수신자·시각·내용을 확인하고 <strong>‘N건 한 번에 등록’</strong>을 한 번 누르면 전체를 순서대로 처리합니다. 배정표 등 업무자료는 ‘자료로 메시지 만들기’에서 일반 양식이나 프리셋으로 가져오세요.</p>${registrationGuide([],state,'help-registration-guide').replace('0건을','선택한 메시지를')}<p>‘등록 요청 완료’는 보내기 요청을 마친 상태입니다. 도착 여부는 조회하지 않습니다. 이미 등록 요청한 메시지는 다시 보내지 않습니다.</p><p>다른 버전의 수동 연결은 쿨메신저 연결 화면에서 설정합니다. ‘1건 자동 입력’으로 확인한 메시지는 그 작성창을 남긴 채 등록을 이어 갈 수 있습니다.</p><p><a href="/google-connection.html" target="_blank" rel="noopener">Google 읽기 연결 준비 방법 ↗</a></p>`,[{text:'확인',action:closeModal}]);}

// Source snapshots are read-only; workflow commit writes drafts, never registers messages.
async function openWorkflow(){if(!wf.from){const next=new Date(state.now.replace(' ','T'));next.setDate(next.getDate()+1);wf.from=localDate(next);wf.to=localDate(new Date(next.getFullYear(),next.getMonth()+1,0));}if(!wf.presets.length){$('workflowContent').innerHTML='<p class="busy-note">업무 양식을 불러오고 있습니다.</p>';try{const [defaults,saved]=await Promise.all([api('workflows/presets',{}),api('workflows/list',{})]);const recipes=saved.recipes||[];wf.presets=recipes.length?recipes.map(recipe=>({id:recipe.id,name:recipe.name,recipe})):defaults;if(!wf.presets.length)throw Error('사용할 업무 양식이 없습니다.');wf.recipe=structuredClone((wf.presets.find(item=>item.id==='general')||wf.presets[0]).recipe);wf.recipe.contact_mapping=wf.recipe.contact_mapping||{};if(saved.source&&Object.keys(saved.source).length)wf.source={...wf.source,...saved.source};try{wf.connection=await api('source/status',{});}catch{wf.connection={connected:false,configured:false};}}catch(error){wf.error=error.message;}}renderWorkflow();}
function wfSourceLabel(){const source=wf.snapshot?.source;return source?source.title||source.sheet_name||source.kind:({google_sheets:'Google 시트',xlsx:'Excel',csv:'CSV',paste:'붙여넣은 표'}[wf.source.kind]||'자료 선택');}
function wfHasRows(){return (wf.snapshot?.values||[]).slice(wf.recipe?.header_rows||(wf.recipe?.preset==='lunch'?2:1)).some(row=>row.some(value=>value!==''&&value!=null));}
function wfErrors(){return wf.error?`<div class="error-box" role="alert">${esc(wf.error)}</div>`:'';}
function wfSteps(){return `<p class="workflow-summary">${wf.step===1?'1. 자료와 기간':wf.step===2?'2. 문구와 수신자':'3. 초안 확인'}</p>`;}
function columnOptions(value){const header=wf.snapshot?.values?.[(wf.recipe?.header_rows||(wf.recipe?.preset==='lunch'?2:1))-1]||[];const names=header.filter(value=>typeof value==='string'&&value.trim());return '<option value="">사용 안 함</option>'+[...new Set([value,...names].filter(Boolean))].map(name=>`<option ${value===name?'selected':''}>${esc(name)}</option>`).join('');}
function workflowPresetOptions(){
  const options=items=>items.map(item=>`<option value="${esc(item.id)}" ${item.id===wf.recipe?.id?'selected':''}>${esc(item.name)}</option>`).join('');
  const general=wf.presets.filter(item=>item.recipe.preset!=='lunch'),presets=wf.presets.filter(item=>item.recipe.preset==='lunch');
  return `<optgroup label="일반 메시지">${options(general)}<option value="__new__">＋ 새 일반 양식</option></optgroup>${presets.length?`<optgroup label="선택 프리셋">${options(presets)}</optgroup>`:''}`;
}
function wfDataHTML(){const source=wf.snapshot?.source;return `<div class="narrow"><button class="back" data-wf="home">← 목록</button>${wfSteps()}<div class="flow-heading"><h1>자료로 메시지 만들기</h1><p class="hint">일반 자료는 한 행에 한 메시지로 만듭니다. 필요한 업무 프리셋도 선택할 수 있습니다.</p></div>${wfErrors()}<div class="flow-fields"><label>메시지 양식<select id="wfPreset">${workflowPresetOptions()}</select><small class="hint">${wf.recipe?.preset==='lunch'?'선택 프리셋 · 중식 배정표에서 담당자 안내를 만듭니다.':'기본 양식 · 받는 사람, 날짜, 내용을 원하는 대로 사용하세요. 제목은 선택입니다.'}</small></label>${wf.recipe?.preset==='lunch'?'<button type="button" class="button quiet small preset-template" data-wf="lunchTemplate">프리셋 엑셀 양식 받기 ↓</button>':''}<div class="flow-two"><label>시작일<input id="wfFrom" type="date" value="${esc(wf.from)}"></label><label>종료일<input id="wfTo" type="date" value="${esc(wf.to)}"></label></div><details class="quick-period"><summary>빠른 기간 선택 · 한 달 전체</summary><label>월 선택<input id="wfMonth" type="month" value="${esc(workflowMonthValue())}"><small class="hint">시작일과 종료일을 선택한 월 전체로 맞춥니다.</small></label></details></div><details class="source-options" open><summary>자료 연결 · ${esc(wfSourceLabel())}</summary><div class="flow-fields"><label>자료 종류<select id="wfKind"><option value="google_sheets" ${wf.source.kind==='google_sheets'?'selected':''}>Google 시트</option><option value="xlsx" ${wf.source.kind==='xlsx'?'selected':''}>Excel</option><option value="csv" ${wf.source.kind==='csv'?'selected':''}>CSV</option><option value="paste" ${wf.source.kind==='paste'?'selected':''}>표 붙여넣기</option></select></label>${wf.source.kind==='google_sheets'?`<label>시트 주소<input id="wfUrl" value="${esc(wf.source.url)}"></label><label>자료 탭${wf.tabs.length?`<select id="wfTab">${wf.tabs.map(tab=>`<option value="${esc(tab.id)}" ${String(tab.id)===String(wf.source.tab_id)?'selected':''}>${esc(tab.title)}</option>`).join('')}</select>`:`<input id="wfTab" value="${esc(wf.source.tab_id)}" placeholder="탭 ID · 주소의 gid 값">`}</label><label>읽을 범위<input id="wfRange" value="${esc(wf.source.range)}" placeholder="예: A1:I500"></label>${wf.recipe?.preset==='lunch'?'<p class="hint">실제 배정 내용이 들어 있는 탭을 선택하세요. 빈 탭에서는 초안을 만들지 않습니다.</p>':''}`:(wf.source.kind==='paste'?`<label>엑셀·시트에서 복사한 표<textarea id="wfPaste" rows="7" placeholder="열 이름을 포함해 표를 복사한 뒤 붙여넣으세요">${esc(wf.paste||'')}</textarea><small class="hint">열 이름을 자동으로 찾습니다. 표 제목과 빈 행도 그대로 붙여넣으세요.</small></label>`:`<label>업무자료 파일<input class="file-choice" id="wfFile" type="file" accept="${wf.source.kind==='xlsx'?'.xlsx':'.csv'}">${wf.file?'<small>'+esc(wf.file.name)+' 선택됨</small>':''}</label><label>시트 이름 · Excel 선택 사항<input id="wfSheetName" value="${esc(wf.source.sheet_name||'')}" placeholder="비우면 첫 시트"></label>`)}<button class="button" data-wf="read" ${wf.busy?'disabled':''}>${wf.busy?'자료를 읽고 있습니다…':'자료 읽기'}</button>${wf.recipe?.preset==='lunch'&&wf.source.kind==='google_sheets'?'<button class="button quiet small" data-wf="cached">이전에 읽은 자료 사용</button>':''}</div></details>${wf.source.kind==='google_sheets'?`<details class="source-options"><summary>Google 읽기 연결 · ${wf.connection.connected?'연결됨':'연결 필요'}</summary><p class="hint">Google 시트는 본인 계정의 읽기 권한을 별도로 승인합니다.</p><p class="hint"><a href="/google-connection.html" target="_blank" rel="noopener">Google 읽기 연결 준비 방법 ↗</a></p><div class="flow-fields"><label>데스크톱 OAuth JSON 전체 경로<input id="wfClientPath" value="${esc(wf.clientPath||'')}" placeholder="OAuth JSON 파일의 전체 경로"></label><div class="button-group"><button class="button small" data-wf="googleConnect">Google 읽기 연결</button><button class="button quiet small" data-wf="googleStatus">연결 상태 확인</button></div></div></details>`:''}${source&&!wfHasRows()?'<p class="notice warning">선택한 탭에 업무자료가 없습니다. 원본의 배정을 완료하거나 자료 탭을 바꾸고 다시 읽으세요.</p>':''}${source?`<p class="notice">${esc(wfSourceLabel())}${wf.headerNotice?'<br>'+esc(wf.headerNotice):''}<br><small>${wf.snapshot.source?.cached?'이전에 읽어 둔 자료 · ':''}${esc(wf.snapshot.read_at||'')}에 읽음 · 이후 원본 변경은 반영되지 않습니다.</small></p>`:''}<div class="flow-actions"><button class="button primary" data-wf="text" ${!wf.snapshotId||!wfHasRows()||wf.busy?'disabled':''}>문구 확인 →</button></div></div>`;}
