  const items=preview.candidates||[],stats=preview.stats||{},diff=preview.diff||{},blockers=preview.blocked||[],pending=workflowPendingJobs(preview),ready=pending.filter(job=>!items.find(item=>item.job.id===job.id)?.issues?.length).length;
