  await refresh();
  const returned=new Set(result.job_ids||[]),ids=selectableJobs().filter(job=>returned.has(job.id)).map(job=>job.id),excluded=returned.size-ids.length;
  selected=new Set(ids);selectionMode=selected.size>0;wf.preview=null;wf.step=1;showView('jobs');refreshTable();
  if(!register){toast(`초안 ${result.saved||0}건 추가 · ${result.updated||0}건 갱신. 아직 예약되지 않았습니다.`);return;}
  if(!ids.length){toast('새로 등록할 초안이 없습니다. 기존 등록 요청은 유지됩니다.');return;}
  const plan=await api('plan',{ids,mode:'register',result_confirmation_mode:resultConfirmationMode()});
  if(plan.errors.length){modal('초안 저장 · 등록 전 확인 필요',`<p>초안을 저장했습니다. 아래 항목을 확인한 뒤 선택한 초안을 다시 검토하세요.</p><div class="error-box">${plan.errors.map(item=>`<strong>${esc(displayTitle(item.title))}</strong>${item.errors.map(error=>`<p>${esc(error)}</p>`).join('')}`).join('')}</div>`,[{text:'닫기',action:closeModal}]);return;}
