document.addEventListener('change',event=>{const el=event.target;if(view!=='workflow'||wf.rendering)return;if(el.id==='wfPreset'){if(el.value==='__new__'){modal('다른 업무 양식','<label>업무 이름<input id="newRecipeName" placeholder="예: 회의 안내"></label>',[{text:'취소',action:()=>{closeModal();renderWorkflow();}},{text:'양식 만들기',primary:true,action:()=>{const name=$('newRecipeName').value.trim();if(!name)throw Error('업무 이름을 입력하세요.');const base=wf.presets.find(item=>item.recipe.preset==='general');wf.recipe=structuredClone(base.recipe);wf.recipe.id='workflow-'+Date.now();wf.recipe.name=name;wf.recipe.contact_mapping={};applyWorkflowHeaderRow();wf.presets.push({id:wf.recipe.id,name,recipe:structuredClone(wf.recipe)});wf.preview=null;wf.dirty=true;closeModal();renderWorkflow();}}]);return;}const item=wf.presets.find(item=>item.id===el.value);if(item){wf.recipe=structuredClone(item.recipe);wf.recipe.contact_mapping=wf.recipe.contact_mapping||{};applyWorkflowHeaderRow();wf.preview=null;wf.dirty=true;renderWorkflow();}}else if(el.id==='wfFile'){wf.file=el.files[0];wf.snapshot=null;wf.snapshotId='';wf.preview=null;wf.dirty=true;const next=document.querySelector('[data-wf="text"]');if(next)next.disabled=true;}else if(el.id==='wfTab'){wf.source.tab_id=el.value;wf.snapshot=null;wf.snapshotId='';wf.preview=null;wf.dirty=true;renderWorkflow();}else if(el.id==='wfKind'){wf.source.kind=el.value;wf.snapshot=null;wf.snapshotId='';wf.preview=null;wf.tabs=[];wf.file=null;renderWorkflow();}else if(el.id==='wfMonth'){if(el.value){const range=workflowMonthRange(el.value);if(wf.from===range.from&&wf.to===range.to)return;Object.assign(wf,range);wf.preview=null;wf.dirty=true;renderWorkflow();}}else if(el.id==='wfHeaderRows'){if(Number(el.value)===wf.recipe?.header_rows)return;wf.headerNotice='';takeWfSettings();wf.preview=null;wf.dirty=true;renderWorkflow();}else if(el.id==='wfFrom'||el.id==='wfTo'){wf[el.id==='wfFrom'?'from':'to']=el.value;wf.dirty=true;}else if(el.matches('.wf-map,.wf-column,.wf-slot')||['wfOffset','wfGrouping','wfSendTime'].includes(el.id)){takeWfSettings();wf.dirty=true;if(wf.step===3)renderWorkflow();}});
document.addEventListener('input',event=>{if(view!=='workflow'||wf.rendering)return;const el=event.target;if(['wfTitle','wfBody','wfName','wfSendTime'].includes(el.id)){takeWfSettings();wf.dirty=true;}if(el.id==='wfPaste'){wf.paste=el.value;wf.snapshot=null;wf.snapshotId='';wf.preview=null;wf.dirty=true;const next=document.querySelector('[data-wf="text"]');if(next)next.disabled=true;}const keys={wfUrl:'url',wfTab:'tab_id',wfRange:'range',wfSheetName:'sheet_name'};if(keys[el.id]){wf.source[keys[el.id]]=el.value;wf.snapshot=null;wf.snapshotId='';wf.preview=null;wf.dirty=true;const next=document.querySelector('[data-wf="text"]');if(next)next.disabled=true;}if(el.id==='wfClientPath')wf.clientPath=el.value;});
let pollingInFlight=false;
async function pollState(){
  if(pollingInFlight||!state||(document.hidden&&!state.runner.active))return;
  pollingInFlight=true;
  try{
    const next=await api('state');
    const changed=next.archived_count!==state.archived_count||next.past_cleanup_count!==state.past_cleanup_count||next.connection_mode!==state.connection_mode||JSON.stringify(next.profile)!==JSON.stringify(profile)||JSON.stringify(next.runner)!==JSON.stringify(state.runner)||JSON.stringify(next.jobs)!==JSON.stringify(state.jobs);
    if(changed)applyState(next);
    else{state.now=next.now;$('clock').textContent=next.now.replaceAll('-','.');}
  }catch{}finally{pollingInFlight=false;}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&polling)pollState();});
async function boot(){if(!token){modal('프로그램에서 시작해 주세요.','<p>프로젝트 폴더의 START.cmd를 실행하면 올바른 접속 창이 열립니다.</p>',[]);return;}try{await refresh();if(updateRequired())return;if(shouldInitializeOnBoot())await initializeConnection(true);polling=setInterval(pollState,1300);}catch(error){modal('연결을 확인해 주세요.',`<p>${esc(error.message)}</p><p>START.cmd를 다시 실행하세요.</p>`,[]);}}
boot();
